create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin') $$;
alter table public.profiles enable row level security; alter table public.categories enable row level security; alter table public.products enable row level security; alter table public.product_images enable row level security; alter table public.product_variants enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.custom_requests enable row level security; alter table public.gallery enable row level security; alter table public.testimonials enable row level security; alter table public.store_settings enable row level security;
create policy "own profile" on public.profiles for select using(id=auth.uid() or public.is_admin());
create policy "public published categories" on public.categories for select using(published or public.is_admin()); create policy "admin categories" on public.categories for all using(public.is_admin()) with check(public.is_admin());
create policy "public published products" on public.products for select using((published and deleted_at is null) or public.is_admin()); create policy "admin products" on public.products for all using(public.is_admin()) with check(public.is_admin());
create policy "images of public products" on public.product_images for select using(exists(select 1 from public.products p where p.id=product_id and p.published and p.deleted_at is null) or public.is_admin()); create policy "admin product images" on public.product_images for all using(public.is_admin()) with check(public.is_admin());
create policy "variants of public products" on public.product_variants for select using(exists(select 1 from public.products p where p.id=product_id and p.published and p.deleted_at is null) or public.is_admin()); create policy "admin variants" on public.product_variants for all using(public.is_admin()) with check(public.is_admin());
create policy "admin orders" on public.orders for all using(public.is_admin()) with check(public.is_admin()); create policy "public creates orders" on public.orders for insert with check(true);
create policy "admin order items" on public.order_items for all using(public.is_admin()) with check(public.is_admin()); create policy "public creates order items" on public.order_items for insert with check(true);
create policy "admin requests" on public.custom_requests for all using(public.is_admin()) with check(public.is_admin()); create policy "public creates requests" on public.custom_requests for insert with check(true);
create policy "public gallery" on public.gallery for select using(published or public.is_admin()); create policy "admin gallery" on public.gallery for all using(public.is_admin()) with check(public.is_admin());
create policy "public testimonials" on public.testimonials for select using(published or public.is_admin()); create policy "admin testimonials" on public.testimonials for all using(public.is_admin()) with check(public.is_admin());
create policy "public settings" on public.store_settings for select using(true); create policy "admin settings" on public.store_settings for all using(public.is_admin()) with check(public.is_admin());
revoke update(role) on public.profiles from authenticated;
